/* tracy-base: dark mode. The palette values WordPress prints on :root are fixed hex, so `color-scheme` alone flips nothing; the dark set restates every colour preset. Values are the Joomla source's dark hook (capture/templates/tracy/css/styles/base.css, html[data-theme=dark]) mapped token for token, each read through its design-system role (var(--ds-c-..., <dark value>)) so a worn system reaches the dark scheme too; the same set applies under prefers-color-scheme when the root element carries no data-theme, which is the 'auto' state (T4 other_default_theme=auto). */
html { color-scheme: light dark; }
html[data-theme="light"] { color-scheme: light; }
html[data-theme="dark"] { color-scheme: dark; }
html[data-theme="dark"] {
  --wp--preset--color--bg: var(--ds-c-bg, #000000);
  --wp--preset--color--surface: var(--ds-c-surface, #1d1d1f);
  --wp--preset--color--surface-warm: var(--ds-c-surface-warm, #0e0e0e);
  --wp--preset--color--fg: var(--ds-c-fg, #f8f8f8);
  --wp--preset--color--fg-2: var(--ds-c-fg-2, #c0c0c1);
  --wp--preset--color--muted: var(--ds-c-muted, #87878b);
  --wp--preset--color--meta: var(--ds-c-meta, #6f6f73);
  --wp--preset--color--border: var(--ds-c-border, #2f2f30);
  --wp--preset--color--border-soft: var(--ds-c-border-soft, #262629);
  --wp--preset--color--accent: var(--ds-c-accent, #2997ff);
  --wp--preset--color--accent-on: var(--ds-c-accent-on, #000000);
  --wp--preset--color--accent-hover: var(--ds-c-accent-hover, #349cff);
  --wp--preset--color--accent-active: var(--ds-c-accent-active, #278ff1);
  --wp--preset--color--success: var(--ds-c-success, #16a34a);
  --wp--preset--color--warn: var(--ds-c-warn, #eab308);
  --wp--preset--color--danger: var(--ds-c-danger, #e45858);
}
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) {
    --wp--preset--color--bg: var(--ds-c-bg, #000000);
    --wp--preset--color--surface: var(--ds-c-surface, #1d1d1f);
    --wp--preset--color--surface-warm: var(--ds-c-surface-warm, #0e0e0e);
    --wp--preset--color--fg: var(--ds-c-fg, #f8f8f8);
    --wp--preset--color--fg-2: var(--ds-c-fg-2, #c0c0c1);
    --wp--preset--color--muted: var(--ds-c-muted, #87878b);
    --wp--preset--color--meta: var(--ds-c-meta, #6f6f73);
    --wp--preset--color--border: var(--ds-c-border, #2f2f30);
    --wp--preset--color--border-soft: var(--ds-c-border-soft, #262629);
    --wp--preset--color--accent: var(--ds-c-accent, #2997ff);
    --wp--preset--color--accent-on: var(--ds-c-accent-on, #000000);
    --wp--preset--color--accent-hover: var(--ds-c-accent-hover, #349cff);
    --wp--preset--color--accent-active: var(--ds-c-accent-active, #278ff1);
    --wp--preset--color--success: var(--ds-c-success, #16a34a);
    --wp--preset--color--warn: var(--ds-c-warn, #eab308);
    --wp--preset--color--danger: var(--ds-c-danger, #e45858);
  }
}
